param([string]$ModelSimBin='C:\modeltech64_10.6d\win64')
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$dir=Join-Path $root 'impl/modelsim_live_fifo_burst';New-Item -ItemType Directory -Force $dir|Out-Null;Push-Location $dir
